<script>
(()=>{const sidebar=document.getElementById('adminSidebar'),menu=document.getElementById('adminMenu'),scrim=document.getElementById('adminScrim');const close=()=>{sidebar.classList.remove('open');scrim.classList.remove('show');menu?.setAttribute('aria-expanded','false')};menu?.addEventListener('click',()=>{const open=sidebar.classList.toggle('open');scrim.classList.toggle('show',open);menu.setAttribute('aria-expanded',String(open))});scrim?.addEventListener('click',close);document.addEventListener('keydown',e=>{if(e.key==='Escape')close()})})();
</script>
